// Parse the Python script output and extract business metrics
const stdout = $input.first().json.stdout || '';
const filePath = $input.first().json.path || '';
const filename = filePath.split('\\').pop() || filePath.split('/').pop();

const lines = stdout.split('\n');
let totalSales = 0;
let gpPercent = 0;
let transactions = 0;
let stockValue = 0;
let alerts = [];
let summaryLines = [];

for (const line of lines) {
  const lower = line.toLowerCase();

  // Extract total sales
  if ((lower.includes('total sales') || lower.includes('net revenue') || lower.includes('gross sales')) && totalSales === 0) {
    const match = line.match(/([\d,]+\.?\d*)/);
    if (match) totalSales = parseFloat(match[1].replace(/,/g, ''));
  }

  // Extract GP margin
  if (lower.includes('gp') || lower.includes('gross profit')) {
    const match = line.match(/(\d+\.?\d*)%/);
    if (match) gpPercent = parseFloat(match[1]);
  }

  // Extract transactions
  if (lower.includes('transaction')) {
    const match = line.match(/(\d+)/);
    if (match) transactions = parseInt(match[1]);
  }

  // Extract stock value
  if (lower.includes('stock') && lower.includes('value')) {
    const match = line.match(/([\d,]+\.?\d*)/);
    if (match) stockValue = parseFloat(match[1].replace(/,/g, ''));
  }

  // Collect alert lines
  if (lower.includes('alert') || lower.includes('critical') || lower.includes('warning') || lower.includes('below cost')) {
    summaryLines.push(line.trim());
  }
}

// Generate alerts based on thresholds
if (gpPercent > 0 && gpPercent < 20) {
  alerts.push(`GP margin ${gpPercent.toFixed(1)}% is BELOW 20% target`);
}
if (totalSales > 0 && totalSales < 400000) {
  alerts.push(`Daily sales Rs.${Math.round(totalSales).toLocaleString()} is BELOW Rs.400,000 threshold`);
}
if (summaryLines.length > 0) {
  alerts = alerts.concat(summaryLines.slice(0, 3));
}

const now = new Date();
const sriLankaTime = now.toLocaleString('en-US', {
  timeZone: 'Asia/Colombo',
  day: '2-digit', month: 'short', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hour12: true
});

return [{
  json: {
    filename,
    filePath,
    totalSales,
    gpPercent,
    transactions,
    stockValue,
    alerts,
    hasAlerts: alerts.length > 0,
    rawOutput: stdout.slice(0, 2000),
    processedAt: sriLankaTime
  }
}];

